const char PAGINA_MESTRE_WEB[] =
    "<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'>"
    "<meta name='viewport' content='width=device-width,initial-scale=1'>"
    "<title>Controle do mestre | UFSM Carro</title><style>"
    ":root{color-scheme:dark;--fundo:#0d141d;--painel:#182431;--painel2:#213142;"
    "--borda:#344b61;--texto:#edf2f7;--fraco:#9fb0c0;--amarelo:#f5b942;"
    "--verde:#62d68b;--vermelho:#ff7c86;--azul:#64b5f6}*{box-sizing:border-box}"
    "body{margin:0;background:var(--fundo);color:var(--texto);font:15px Arial,sans-serif}"
    "main{max-width:1050px;margin:auto;padding:18px}header{display:flex;gap:14px;"
    "align-items:flex-start;justify-content:space-between;flex-wrap:wrap;margin-bottom:16px}"
    "[hidden]{display:none!important}h1{font-size:1.65rem;margin:0;color:var(--amarelo)}h2{font-size:1.15rem;margin:25px 0 5px}h3{font-size:.95rem;margin:0 0 10px}"
    "p{color:var(--fraco);line-height:1.45}.navegacao{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.navegacao a{color:var(--texto);text-decoration:none;background:var(--painel2);border:1px solid var(--borda);padding:7px 10px;border-radius:8px}"
    ".selo{padding:8px 11px;border-radius:999px;background:var(--painel2);font-weight:bold}"
    ".sucesso{color:var(--verde)}.erro{color:var(--vermelho)}.processando{color:var(--amarelo)}"
    ".neutro{color:var(--fraco)}.layout-principal{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:18px;align-items:start}.conteudo{min-width:0}.controles{min-width:0}.painel-resultado{background:#111b25;border:1px solid #223547;border-radius:14px;padding:16px}.grade{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:11px}"
    ".cartao{background:var(--painel);border:1px solid #223547;border-radius:12px;padding:14px}"
    ".cartao.largo{grid-column:1/-1}.cabecalho-secao{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:20px 0 11px}.cabecalho-secao h2{margin:0}.cabecalho-secao p{margin:5px 0 0}"
    ".rotulo{font-size:.74rem;text-transform:uppercase;letter-spacing:.06em;color:var(--fraco)}"
    ".valor{font-size:1.15rem;font-weight:bold;margin-top:7px;overflow-wrap:anywhere}.detalhe{color:var(--fraco);font-size:.86rem;margin-top:6px;min-height:1em;line-height:1.4}"
    ".barra{height:8px;background:#0b1118;border-radius:8px;overflow:hidden;margin-top:10px}"
    ".barra>span{display:block;width:0;height:100%;background:var(--azul);transition:width .25s}"
    ".alvos{margin-top:12px;border-top:1px solid var(--borda);padding-top:8px}.alvo{display:grid;grid-template-columns:75px 1fr auto;gap:8px;padding:5px 0;font-size:.84rem}"
    ".grupo{background:#121d28;border:1px solid #203244;border-radius:12px;padding:0;margin-top:10px;overflow:hidden}.grupo>summary{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:13px 14px;cursor:pointer;font-weight:bold;list-style:none}.grupo>summary::-webkit-details-marker{display:none}.grupo>summary:after{content:'+';color:var(--amarelo);font-size:1.2rem}.grupo[open]>summary:after{content:'−'}.grupo>summary small{color:var(--fraco);font-weight:normal}.comandos{display:flex;flex-direction:column;gap:8px;padding:0 10px 10px}"
    "button{width:100%;background:var(--painel2);color:var(--texto);border:1px solid var(--borda);border-radius:9px;padding:12px;text-align:left;font:inherit;cursor:pointer;transition:border-color .15s,transform .15s}"
    "button:hover{border-color:var(--amarelo);transform:translateY(-1px)}button:disabled{opacity:.5;cursor:wait;transform:none}button strong{display:block;margin-bottom:4px}button small{display:block;color:var(--fraco);line-height:1.35}button.ativo{border-color:var(--azul);box-shadow:0 0 0 1px var(--azul) inset;background:#182d40}button.secundario{width:auto;padding:9px 12px}button.primario{width:auto;min-width:245px;background:#2b2518;border-color:#8c6a22}"
    "button.acao{background:#211d17;border-left:5px solid var(--amarelo);padding-left:13px}button.acao:before{content:'EXIGE CONFIRMAÇÃO';display:block;color:var(--amarelo);font-size:.64rem;font-weight:bold;letter-spacing:.08em;margin-bottom:5px}button.acao:hover{background:#2a2318}button.perigo{border-left-color:var(--vermelho);background:#26191d}"
    ".estado{margin:15px 0;padding:12px 14px;border-radius:9px;background:var(--painel2);border:1px solid var(--borda);font-weight:500}"
    ".confirmacao{background:#291f12;border:1px solid #6e5421;border-left:5px solid var(--amarelo);padding:15px;border-radius:10px;margin:12px 0}.confirmacao[hidden]{display:none}.confirmacao p{margin:7px 0 0}"
    ".linha-botoes{display:flex;gap:8px;flex-wrap:wrap;margin-top:11px}.linha-botoes button{padding:9px 13px}"
    ".tecnico{margin-top:13px;background:#111b25;border:1px solid #26394b;border-radius:9px;padding:10px 12px}.tecnico summary{cursor:pointer;color:var(--fraco)}"
    "details{margin-top:9px}pre{white-space:pre-wrap;word-break:break-word;background:#071019;color:#b9efca;padding:12px;border-radius:8px;max-height:300px;overflow:auto}"
    ".historico{list-style:none;padding:0;margin:0}.historico li{display:grid;grid-template-columns:75px 1fr auto;gap:9px;border-bottom:1px solid #26394b;padding:9px 2px}.historico small{color:var(--fraco)}"
    ".historico-bloco{margin-top:24px;background:#111b25;border:1px solid #223547;border-radius:12px;padding:0 14px 10px}"
    "@media(max-width:820px){.layout-principal{grid-template-columns:1fr}.controles{order:2}.painel-resultado{padding:14px}}@media(max-width:560px){main{padding:14px}.cabecalho-secao{align-items:flex-start}.cabecalho-secao button{width:100%}.alvo{grid-template-columns:65px 1fr}.alvo span:last-child{grid-column:2}.historico li{grid-template-columns:65px 1fr}.historico small{grid-column:2}button.primario{width:100%}}"
    "</style></head><body><main><header><div><h1>Controle remoto do mestre</h1>"
    "<p>Comandos confirmados pela UART do satélite da equipe.</p><div class='navegacao'><a href='/'>Telemetria</a><a href='/diagnostico'>Diagnóstico</a></div></div>"
    "<span id='conexao' class='selo neutro'>Ainda não consultado</span></header>"
    "<div id='estado' class='estado neutro'>Pronto para enviar um comando.</div>"
    "<div class='linha-botoes'><button id='atualizar' class='primario'><strong>Atualizar visão geral</strong><small>Comunicação, versão, saúde, OTA e Wi-Fi</small></button></div>"
    "<div class='layout-principal'><div class='conteudo'><section id='resultadoGeral' class='painel-resultado'><div class='cabecalho-secao'><div><h2>Visão geral</h2><p>Resumo dos principais estados do mestre.</p></div></div><div class='grade'>"
    "<article class='cartao'><div class='rotulo'>Comunicação</div><div id='linkValor' class='valor'>—</div><div id='linkDetalhe' class='detalhe'>Nenhuma resposta recebida</div></article>"
    "<article class='cartao'><div class='rotulo'>Firmware mestre</div><div id='versaoValor' class='valor'>—</div><div id='versaoDetalhe' class='detalhe'>Capacidades ainda não consultadas</div></article>"
    "<article class='cartao'><div class='rotulo'>Saúde do mestre</div><div id='saudeValor' class='valor'>—</div><div id='saudeDetalhe' class='detalhe'>—</div></article>"
    "<article class='cartao'><div class='rotulo'>Wi-Fi do mestre</div><div id='wifiValor' class='valor'>—</div><div id='wifiDetalhe' class='detalhe'>—</div></article>"
    "<article class='cartao' style='grid-column:1/-1'><div class='rotulo'>Atualização OTA</div><div id='otaValor' class='valor'>—</div><div id='otaDetalhe' class='detalhe'>—</div>"
    "<div class='barra'><span id='otaBarra'></span></div><div class='alvos'>"
    "<div class='alvo'><b>Mestre</b><span id='otaMestre'>—</span><span id='otaMestreVersao'>—</span></div>"
    "<div class='alvo'><b>Equipe</b><span id='otaEquipe'>—</span><span id='otaEquipeVersao'>—</span></div>"
    "<div class='alvo'><b>Visitantes</b><span id='otaVisitantes'>—</span><span id='otaVisitantesVersao'>—</span></div>"
    "</div></article></div></section>"
    "<section id='resultadoConsulta' class='painel-resultado' hidden><div class='cabecalho-secao'><div><h2 id='tituloConsulta'>Resultado da consulta</h2><p id='descricaoConsulta'>—</p></div><button id='voltarGeral' class='secundario'>Voltar à visão geral</button></div>"
    "<div id='detalhesConsulta' class='grade'></div><details class='tecnico'><summary>Dados técnicos desta resposta</summary><div id='metaResposta' class='detalhe'>—</div><pre id='saida'>{}</pre></details></section></div>"
    "<aside class='controles'><div class='cabecalho-secao'><div><h2>Consultas</h2><p>Mostra somente os dados do assunto escolhido.</p></div></div>"
    "<details class='grupo' open><summary><span>Sistema do mestre <small>4 consultas</small></span></summary><div class='comandos'>"
    "<button data-consulta='ping'><strong>Ping</strong><small>Confirma o enlace e mede o tempo de resposta</small></button>"
    "<button data-consulta='versao'><strong>Versão</strong><small>Firmware, nó e capacidades anunciadas</small></button>"
    "<button data-consulta='capacidades'><strong>Capacidades</strong><small>Recursos aceitos pelo protocolo</small></button>"
    "<button data-consulta='saude'><strong>Saúde</strong><small>Estado, causas, memória e erros históricos</small></button></div></details>"
    "<details class='grupo'><summary><span>Dados e comunicação <small>4 consultas</small></span></summary><div class='comandos'>"
    "<button data-consulta='telemetria'><strong>Telemetria no mestre</strong><small>Última amostra mantida pelo mestre</small></button>"
    "<button data-consulta='uart'><strong>UART da equipe</strong><small>Envios, recepções, erros e descartes</small></button>"
    "<button data-consulta='ota'><strong>Estado OTA</strong><small>Situação e versões de cada firmware</small></button>"
    "<button data-consulta='wifi'><strong>Wi-Fi do mestre</strong><small>Rádio, conexão, RSSI e rede atual</small></button></div></details>"
    "<div class='cabecalho-secao'><div><h2>Ações com confirmação</h2><p>As caixas com a faixa laranja alteram o estado do mestre.</p></div></div><details class='grupo' open><summary><span>Atualização e diagnóstico <small>6 ações</small></span></summary><div class='comandos'>"
    "<button class='acao' data-acao='verificar_ota' data-pergunta='Solicitar ao mestre uma nova verificação de atualizações?'><strong>Verificar atualizações</strong><small>Abre uma sessão Wi-Fi temporária no mestre</small></button>"
    "<button class='acao' data-acao='autorizar_mestre' data-pergunta='Autorizar a instalação da atualização do mestre?'><strong>Autorizar OTA do mestre</strong><small>Disponível quando houver firmware pendente</small></button>"
    "<button class='acao' data-acao='autorizar_equipe' data-pergunta='Autorizar a atualização deste satélite da equipe?'><strong>Autorizar OTA da equipe</strong><small>O mestre enviará o firmware pela UART</small></button>"
    "<button class='acao' data-acao='autorizar_visitantes' data-pergunta='Autorizar a atualização do satélite de visitantes?'><strong>Autorizar OTA de visitantes</strong><small>O mestre enviará o firmware pela UART</small></button>"
    "<button class='acao perigo' data-acao='cancelar_ota' data-pergunta='Cancelar todas as atualizações OTA pendentes?'><strong>Cancelar OTA</strong><small>Cancela autorizações e transferências pendentes</small></button>"
    "<button class='acao' data-acao='resumo_terminal' data-pergunta='Solicitar um resumo no terminal serial do mestre?'><strong>Resumo no terminal</strong><small>Exibe os relatórios no console do mestre</small></button></div></details>"
    "<div id='confirmacao' class='confirmacao' hidden><strong id='pergunta'></strong><p>O comando será enviado ao mestre e a resposta deverá chegar pela UART.</p>"
    "<div class='linha-botoes'><button id='confirmar'>Confirmar envio</button><button id='voltar'>Voltar</button></div></div></aside></div>"
    "<section class='historico-bloco'><div class='cabecalho-secao'><div><h2>Histórico desta página</h2><p>Últimos comandos enviados neste navegador.</p></div></div><ul id='historico' class='historico'><li><span>—</span><span>Nenhum comando enviado</span><small>—</small></li></ul></section>"
    "</main><script>"
    "const $=i=>document.getElementById(i),estado=$('estado'),conexao=$('conexao'),saida=$('saida'),historico=$('historico');"
    "let pendente='',ocupado=false,cicloOta=0,primeiroHistorico=true;"
    "const nomesSaude=['Saudável','Recuperando','Atenção','Falha'];"
    "const nomesOta=['Desabilitado','Inicializando','Aguardando rede','Verificando','Atualizado','Aguardando autorização','Baixando','Aplicado','Cancelado','Falha'];"
    "const nomesOtaSat=['Desconhecido','Indisponível','Não suportado','Atualizado','Aguardando autorização','Transferindo','Reiniciando','Concluído','Cancelado','Falha'];"
    "const nomeAlvo=['nenhum','mestre','equipe','visitantes'],nomeNo=['desconhecido','mestre','equipe','visitantes'];"
    "const capacidades=[[1,'Ping'],[2,'Versão'],[4,'Saúde'],[8,'Telemetria'],[16,'UART'],[32,'OTA'],[64,'Wi-Fi'],[128,'Controle OTA'],[256,'Terminal']];"
    "function texto(i,v){$(i).textContent=v}function classeMensagem(t,c){estado.textContent=t;estado.className='estado '+c}"
    "function atualizarBotoes(){document.querySelectorAll('button').forEach(b=>b.disabled=ocupado)}"
    "function bloquear(v){ocupado=v;atualizarBotoes()}function versao(a,d){return a||d||'—'}function percentual(v){return Math.max(0,Math.min(100,Number(v)||0))}"
    "function formatarTempo(ms){ms=Number(ms)||0;if(ms<60000)return Math.round(ms/1000)+' s';if(ms<3600000)return(ms/60000).toFixed(1)+' min';return(ms/3600000).toFixed(1)+' h'}"
    "function listaCapacidades(m){m=Number(m)||0;let n=capacidades.filter(c=>(m&c[0])!==0).map(c=>c[1]);return n.length?n.join(', '):'Nenhuma capacidade reconhecida'}"
    "function qualidadeRssi(r){r=Number(r);if(r>=-50)return'Excelente';if(r>=-60)return'Muito bom';if(r>=-70)return'Bom';if(r>=-80)return'Fraco';return'Muito fraco'}"
    "function registrar(d,ok){if(primeiroHistorico){historico.innerHTML='';primeiroHistorico=false}let li=document.createElement('li'),hora=document.createElement('span'),descricao=document.createElement('span'),meta=document.createElement('small');"
    "hora.textContent=new Date().toLocaleTimeString();descricao.className=ok?'sucesso':'erro';descricao.textContent=(d.consulta||d.acao||'comando')+' · '+(ok?'confirmado':(d.erro||'falhou'));meta.textContent='#'+(d.solicitacao||0)+' · '+(d.duracao_ms||0)+' ms';li.append(hora,descricao,meta);historico.prepend(li);while(historico.children.length>12)historico.lastChild.remove()}"
    "function atualizarMeta(d){texto('metaResposta','Comando '+(d.comando||'—')+' · solicitação #'+(d.solicitacao||0)+' · '+(d.tentativas||0)+' tentativa(s) · '+(d.duracao_ms||0)+' ms');saida.textContent=JSON.stringify(d,null,2)}"
    "function selecionar(c){document.querySelectorAll('[data-consulta]').forEach(b=>b.classList.toggle('ativo',b.dataset.consulta===c))}"
    "function criarCartao(item){let a=document.createElement('article'),r=document.createElement('div'),v=document.createElement('div'),d=document.createElement('div');a.className='cartao'+(item.largo?' largo':'');r.className='rotulo';v.className='valor';d.className='detalhe';r.textContent=item.rotulo;v.textContent=item.valor;d.textContent=item.detalhe||'';a.append(r,v,d);if(item.progresso!==undefined){let b=document.createElement('div'),s=document.createElement('span');b.className='barra';s.style.width=percentual(item.progresso)+'%';b.append(s);a.append(b)}return a}"
    "function exibirConsulta(titulo,descricao,itens,d,semRolagem){texto('tituloConsulta',titulo);texto('descricaoConsulta',descricao);let grade=$('detalhesConsulta');grade.replaceChildren();itens.forEach(i=>grade.append(criarCartao(i)));$('resultadoGeral').hidden=true;$('resultadoConsulta').hidden=false;selecionar(d.consulta);atualizarMeta(d);if(!semRolagem)window.scrollTo({top:0,behavior:'smooth'})}"
    "function versoesAlvo(o){if(!o)return'Informação indisponível';return versao(o.versao_atual,'desconhecida')+(o.versao_disponivel?' → '+o.versao_disponivel:' · sem atualização')}"
    "function modeloConsulta(d){let hex=v=>'0x'+(Number(v)||0).toString(16).toUpperCase();"
    "if(d.consulta==='ping')return['Comunicação com o mestre','Resultado exclusivo do teste de enlace UART',[{rotulo:'Tempo de resposta',valor:d.rtt_ms+' ms',detalhe:d.tentativas+' tentativa(s)'},{rotulo:'Tempo ativo do mestre',valor:formatarTempo(d.tempo_ativo_ms),detalhe:d.tempo_ativo_ms+' ms desde a inicialização'},{rotulo:'Solicitação',valor:'#'+d.solicitacao,detalhe:'Resposta correlacionada e validada'}]];"
    "if(d.consulta==='versao')return['Versão do mestre','Identificação do firmware em execução',[{rotulo:'Firmware',valor:d.firmware,detalhe:'Versão informada pelo mestre'},{rotulo:'Nó do protocolo',valor:nomeNo[d.no]||('nó '+d.no),detalhe:'Identificador '+d.no},{rotulo:'Capacidades',valor:hex(d.capacidades),detalhe:listaCapacidades(d.capacidades),largo:true}]];"
    "if(d.consulta==='capacidades')return['Capacidades do mestre','Funções anunciadas pelo protocolo de comandos',[{rotulo:'Máscara recebida',valor:hex(d.capacidades),detalhe:'Valor anunciado pelo mestre'},{rotulo:'Recursos reconhecidos',valor:listaCapacidades(d.capacidades),detalhe:'Novos bits continuam compatíveis com o mesmo quadro',largo:true}]];"
    "if(d.consulta==='saude')return['Saúde do mestre','Estado atual do sistema e indicadores acumulados',[{rotulo:'Estado',valor:nomesSaude[d.estado]||('Estado '+d.estado),detalhe:'Classificação calculada pelo serviço de saúde'},{rotulo:'Causas ativas',valor:hex(d.causas_ativas),detalhe:d.causas_ativas?'Existem causas ativas':'Nenhuma causa ativa'},{rotulo:'Memória livre',valor:(d.heap_livre/1024).toFixed(1)+' KiB',detalhe:'Heap disponível no momento'},{rotulo:'Erros históricos',valor:d.erros_historicos,detalhe:'Ocorrências acumuladas'},{rotulo:'Tempo ativo',valor:formatarTempo(d.tempo_ativo_ms),detalhe:d.tempo_ativo_ms+' ms'}]];"
    "if(d.consulta==='telemetria')return['Telemetria no mestre','Última amostra mantida pelo serviço de telemetria',[{rotulo:'Velocidade',valor:d.velocidade_kmh.toFixed(1)+' km/h',detalhe:'Valor processado pelo mestre'},{rotulo:'Carga da bateria',valor:d.carga_percentual.toFixed(1)+'%',detalhe:'Estimativa recebida'},{rotulo:'ADC bruto',valor:d.adc,detalhe:'Leitura sem conversão'},{rotulo:'Sequência',valor:'#'+d.sequencia,detalhe:'Tempo do mestre: '+d.tempo_mestre_ms+' ms'}]];"
    "if(d.consulta==='uart')return['UART entre equipe e mestre','Contadores do canal do satélite da equipe',[{rotulo:'Envios concluídos',valor:d.envios,detalhe:'Quadros transmitidos pelo mestre'},{rotulo:'Recepções',valor:d.recepcoes,detalhe:'Quadros recebidos pelo mestre'},{rotulo:'Erros',valor:d.erros,detalhe:d.erros?'Requer atenção':'Nenhum erro acumulado'},{rotulo:'Descartes',valor:d.descartes,detalhe:d.descartes?'Mensagens descartadas':'Nenhum descarte acumulado'}]];"
    "if(d.consulta==='wifi')return['Wi-Fi do mestre','Estado atual do rádio e da conexão externa',[{rotulo:'Estado do rádio',valor:d.conectado?'Conectado':(d.radio_ativo?'Ativo, sem conexão':'Em repouso'),detalhe:d.conectado?'Sessão Wi-Fi estabelecida':'Nenhuma rede conectada'},{rotulo:'Rede',valor:d.rede||'sem rede',detalhe:'SSID informado pelo mestre'},{rotulo:'Sinal',valor:d.conectado?d.rssi_dbm+' dBm':'—',detalhe:d.conectado?qualidadeRssi(d.rssi_dbm):'RSSI indisponível'},{rotulo:'Canal',valor:d.canal||'—',detalhe:'Canal Wi-Fi atual'}]];"
    "if(d.consulta==='ota'){let detalhado=d.mestre&&d.equipe&&d.visitantes,m=detalhado?d.mestre:{estado:d.estado,progresso_percentual:d.progresso_percentual,versao_atual:d.versao_atual,versao_disponivel:d.versao_disponivel},e=detalhado?d.equipe:null,v=detalhado?d.visitantes:null;let itens=[{rotulo:'Estado geral',valor:nomesOta[d.estado]||('Estado '+d.estado),detalhe:'Alvo ativo: '+(nomeAlvo[d.alvo]||d.alvo)+' · '+(d.verificacoes||0)+' verificação(ões) · '+(d.falhas||0)+' falha(s)',largo:true},{rotulo:'Mestre',valor:nomesOta[m.estado]||('Estado '+m.estado),detalhe:versoesAlvo(m),progresso:m.progresso_percentual}];if(e)itens.push({rotulo:'Satélite da equipe',valor:nomesOtaSat[e.estado]||('Estado '+e.estado),detalhe:versoesAlvo(e),progresso:e.progresso_percentual});if(v)itens.push({rotulo:'Satélite de visitantes',valor:nomesOtaSat[v.estado]||('Estado '+v.estado),detalhe:versoesAlvo(v),progresso:v.progresso_percentual});return['Atualizações OTA','Estado e versões dos firmwares conhecidos pelo mestre',itens]}return null}"
    "function apresentarConsulta(d,semRolagem){let m=modeloConsulta(d);if(m)exibirConsulta(m[0],m[1],m[2],d,semRolagem)}"
    "function apresentarErro(c,d){exibirConsulta('Falha na consulta','O mestre não forneceu os dados solicitados',[{rotulo:'Consulta',valor:c,detalhe:'Comando solicitado'},{rotulo:'Motivo',valor:d.erro||'Falha desconhecida',detalhe:(d.tentativas||0)+' tentativa(s) · '+(d.duracao_ms||0)+' ms',largo:true}],d)}"
    "function aplicarOta(d){let detalhado=d.mestre&&d.equipe&&d.visitantes,m=detalhado?d.mestre:{estado:d.estado,progresso_percentual:d.progresso_percentual,versao_atual:d.versao_atual,versao_disponivel:d.versao_disponivel};"
    "let e=detalhado?d.equipe:null,v=detalhado?d.visitantes:null,ativo=d.alvo||0,progresso=ativo===2&&e?e.progresso_percentual:ativo===3&&v?v.progresso_percentual:(m.progresso_percentual||0);"
    "texto('otaValor',nomesOta[d.estado]||('Estado '+d.estado));texto('otaDetalhe','Alvo ativo: '+(nomeAlvo[ativo]||ativo)+' · '+(d.falhas||0)+' falha(s) · '+(d.verificacoes||0)+' verificação(ões)');$('otaBarra').style.width=percentual(progresso)+'%';"
    "texto('otaMestre',nomesOta[m.estado]||('Estado '+m.estado));texto('otaMestreVersao',versoesAlvo(m));"
    "texto('otaEquipe',e?(nomesOtaSat[e.estado]||('Estado '+e.estado)):'formato legado');texto('otaEquipeVersao',e?versoesAlvo(e):'—');"
    "texto('otaVisitantes',v?(nomesOtaSat[v.estado]||('Estado '+v.estado)):'formato legado');texto('otaVisitantesVersao',v?versoesAlvo(v):'—')}"
    "function aplicar(d){if(!d||!d.ok)return;if(d.consulta==='ping'){texto('linkValor',d.rtt_ms+' ms');texto('linkDetalhe','Resposta em '+d.tentativas+' tentativa(s) · mestre ativo há '+formatarTempo(d.tempo_ativo_ms));conexao.textContent='Mestre respondendo';conexao.className='selo sucesso'}"
    "else if(d.consulta==='versao'){texto('versaoValor',d.firmware);texto('versaoDetalhe','Nó '+(nomeNo[d.no]||d.no)+' · '+listaCapacidades(d.capacidades))}"
    "else if(d.consulta==='capacidades'){texto('versaoDetalhe','Capacidades 0x'+Number(d.capacidades).toString(16).toUpperCase())}"
    "else if(d.consulta==='saude'){texto('saudeValor',nomesSaude[d.estado]||('Estado '+d.estado));texto('saudeDetalhe','Causas 0x'+Number(d.causas_ativas).toString(16).toUpperCase()+' · heap '+(d.heap_livre/1024).toFixed(1)+' KiB · erros '+d.erros_historicos)}"
    "else if(d.consulta==='wifi'){texto('wifiValor',d.conectado?'Conectado':(d.radio_ativo?'Rádio ativo':'Em repouso'));texto('wifiDetalhe',(d.rede||'sem rede')+' · '+(d.conectado?d.rssi_dbm+' dBm':'sem RSSI')+' · canal '+d.canal)}"
    "else if(d.consulta==='ota')aplicarOta(d)}"
    "async function executar(c,metodo,opt){opt=opt||{};if(ocupado&&!opt.interno)return null;if(!opt.silencioso){pendente='';$('confirmacao').hidden=true;bloquear(true);classeMensagem('Enviando '+c+' e aguardando a confirmação pela UART...','processando')}"
    "let controlador=new AbortController(),limite=setTimeout(()=>controlador.abort(),16000);try{let r=await fetch('/api/mestre?consulta='+encodeURIComponent(c),{method:metodo||'GET',cache:'no-store',signal:controlador.signal});let corpo=await r.text(),d;try{d=JSON.parse(corpo)}catch(_){throw new Error('resposta HTTP inválida')}"
    "aplicar(d);if(!opt.silencioso){registrar(d,r.ok&&d.ok);if((metodo||'GET')==='GET'){if(r.ok&&d.ok)apresentarConsulta(d);else apresentarErro(c,d)}classeMensagem(r.ok&&d.ok?'Comando confirmado pelo mestre.':(d.erro||'Comando recusado.'),r.ok&&d.ok?'sucesso':'erro')}"
    "if(!r.ok||!d.ok){if(c==='ping'){conexao.textContent='Mestre sem resposta';conexao.className='selo erro'}return null}return d}catch(e){let d={ok:false,consulta:c,erro:e.name==='AbortError'?'tempo limite da página excedido':e.message,solicitacao:0,duracao_ms:0};"
    "if(!opt.silencioso){registrar(d,false);if((metodo||'GET')==='GET')apresentarErro(c,d);classeMensagem('Não foi possível concluir o comando.','erro')}if(c==='ping'){conexao.textContent='Mestre sem resposta';conexao.className='selo erro'}return null}finally{clearTimeout(limite);if(!opt.silencioso)bloquear(false)}}"
    "function abrirGeral(){cicloOta++;selecionar('');$('resultadoConsulta').hidden=true;$('resultadoGeral').hidden=false;window.scrollTo({top:0,behavior:'smooth'})}"
    "async function visaoGeral(){if(ocupado)return;cicloOta++;selecionar('');$('resultadoConsulta').hidden=true;$('resultadoGeral').hidden=false;bloquear(true);classeMensagem('Atualizando a visão geral...','processando');let p=await executar('ping','GET',{silencioso:true,interno:true}),sucessos=p?1:0;if(p){for(const c of ['versao','saude','ota','wifi'])if(await executar(c,'GET',{silencioso:true,interno:true}))sucessos++;classeMensagem(sucessos===5?'Visão geral atualizada.':'Visão geral atualizada parcialmente: '+sucessos+' de 5 consultas.',sucessos===5?'sucesso':'processando')}else classeMensagem('O mestre não respondeu ao teste de comunicação.','erro');bloquear(false)}"
    "function preparar(c,p){if(ocupado)return;cicloOta++;pendente=c;texto('pergunta',p);$('confirmacao').hidden=false;$('confirmacao').scrollIntoView({behavior:'smooth',block:'center'})}"
    "async function confirmar(){if(!pendente)return;let c=pendente;pendente='';$('confirmacao').hidden=true;let d=await executar(c,'POST');if(d&&d.ok&&c!=='resumo_terminal'){let atual=await executar('ota','GET',{silencioso:true});if(atual)apresentarConsulta(atual);let meu=++cicloOta;acompanharOta(meu,c)}}"
    "function cancelar(){pendente='';$('confirmacao').hidden=true;classeMensagem('Ação cancelada localmente. Nenhum comando foi enviado.','neutro')}"
    "async function acompanharOta(meu,acao){for(let i=0;i<90&&meu===cicloOta;i++){await new Promise(r=>setTimeout(r,2000));let d=await executar('ota','GET',{silencioso:true});if(!d)return;apresentarConsulta(d,true);let final=[4,7,8,9].includes(d.estado)||(acao==='verificar_ota'&&d.estado===5);if(i>0&&final){classeMensagem('Operação OTA: '+(nomesOta[d.estado]||d.estado)+'.',d.estado===9?'erro':'sucesso');return}}}"
    "document.querySelectorAll('[data-consulta]').forEach(b=>b.onclick=()=>{cicloOta++;executar(b.dataset.consulta,'GET')});document.querySelectorAll('[data-acao]').forEach(b=>b.onclick=()=>preparar(b.dataset.acao,b.dataset.pergunta));"
    "$('atualizar').onclick=visaoGeral;$('voltarGeral').onclick=abrirGeral;$('confirmar').onclick=confirmar;$('voltar').onclick=cancelar;visaoGeral();"
    "</script></body></html>";
